import os
import pty
import select
import signal
import termios
import time
import fcntl
from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """A headless terminal implementation using a pseudo-terminal (PTY).

    Spawns an interactive bash shell in a PTY so keystrokes behave as if typed
    by a user. Supports interactive programs, modifier/control keys (e.g.,
    \x03 for Ctrl+C), and sources bash startup files (interactive shell).
    """

    def __init__(self):
        master_fd, slave_fd = pty.openpty()

        pid = os.fork()

        if pid == 0:
            # Child process
            os.close(master_fd)

            # New session with the slave as the controlling terminal
            os.setsid()
            try:
                fcntl.ioctl(slave_fd, termios.TIOCSCTTY, 0)
            except OSError:
                pass

            os.dup2(slave_fd, 0)
            os.dup2(slave_fd, 1)
            os.dup2(slave_fd, 2)

            if slave_fd > 2:
                os.close(slave_fd)

            os.execvp("bash", ["bash", "-i"])
        else:
            # Parent process
            os.close(slave_fd)
            self.master_fd = master_fd
            self.child_pid = pid
            self.output = b""
            # Let the shell start up and print its first prompt
            self._pump(0.5)

    def _pump(self, timeout=0.0):
        """Read all currently available data, blocking up to timeout seconds."""
        data = b""
        deadline = time.monotonic() + timeout
        while True:
            remaining = deadline - time.monotonic()
            if remaining < 0:
                remaining = 0
            r, _, _ = select.select([self.master_fd], [], [], remaining)
            if r:
                try:
                    chunk = os.read(self.master_fd, 65536)
                except OSError:
                    break
                if chunk:
                    data += chunk
                else:
                    break
            else:
                break
        self.output += data
        return data

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send keystrokes to the terminal.

        Args:
            keystrokes: The keystrokes to send to the terminal.
            wait_sec: Seconds to wait for the command to complete.
        """
        to_send = keystrokes.encode("utf-8") if isinstance(keystrokes, str) else keystrokes
        os.write(self.master_fd, to_send)

        if wait_sec > 0:
            self._pump(wait_sec)

    def get_output(self):
        """Return all accumulated output so far (as bytes)."""
        return self.output

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass

    def close(self):
        """Terminate the child process and close file descriptors."""
        try:
            os.kill(self.child_pid, signal.SIGKILL)
        except (ProcessLookupError, OSError):
            pass
        try:
            os.waitpid(self.child_pid, os.WNOHANG)
        except ChildProcessError:
            pass
        try:
            os.close(self.master_fd)
        except OSError:
            pass
